package com.ruoyi.medical.persistence;
import com.ruoyi.medical.persistence.mapper.*;import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
@Configuration @ConditionalOnProperty(prefix="medical.runtime-retention",name="enabled",havingValue="true")
public class RuntimeRetentionConfiguration {
 @Bean RuntimeRetentionCancellation runtimeRetentionCancellation(EnterpriseAccess access,RuntimeRetentionMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,RuntimeRetentionAuthority authority,RuntimeRetentionSchema schema,PermissionSchema json){return new RuntimeRetentionCancellation(access,mapper,permissions,resources,authority,schema,json);}
 @Bean RuntimeRetentionSchema runtimeRetentionSchema()throws Exception{return new RuntimeRetentionSchema();}
 @Bean RuntimeRetentionAuthority runtimeRetentionAuthority(RuntimeRetentionMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,PermissionAuthority grants,RuntimeRetentionSchema schema,com.ruoyi.medical.identity.PlatformMemberIdentityStatus identities,@org.springframework.beans.factory.annotation.Value("${medical.runtime-retention.maximum-candidates}") int maximumCandidates){return new RuntimeRetentionAuthority(mapper,permissions,resources,grants,schema,identities,maximumCandidates);}
 @Bean RuntimeRetentionService runtimeRetentionService(EnterpriseAccess access,RuntimeRetentionMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,RuntimeRetentionAuthority authority,RuntimeRetentionSchema schema,PermissionSchema json,RuntimeRetentionDecisions decisions){return new RuntimeRetentionService(access,mapper,permissions,resources,authority,schema,json,decisions);}
 @Bean RuntimeRetentionDecisions runtimeRetentionDecisions(EnterpriseAccess access,RuntimeRetentionMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,RuntimeRetentionAuthority authority,RuntimeRetentionSchema schema,PermissionSchema json){return new RuntimeRetentionDecisions(access,mapper,permissions,resources,authority,schema,json);}
 @Bean RuntimeRetentionReads runtimeRetentionReads(EnterpriseAccess access,RuntimeRetentionMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,RuntimeRetentionAuthority authority,RuntimeRetentionSchema schema,PermissionSchema json){return new RuntimeRetentionReads(access,mapper,permissions,resources,authority,schema,json);}
}
